1	package warranty
2	
3	import (
4		"fmt"
5		"sync"
6		"time"
7	)
8	
9	// Product 是登记的产品保修信息。
10	type Product struct {
11		// ID 是唯一产品编号。
12		ID string
13		// PurchaseTime 是购买时刻。
14		PurchaseTime time.Time
15		// WarrantyDays 是保修天数，必须为正整数；保修期自购买时刻起，每天按二十四小时计算。
16		WarrantyDays int
17		// ExcludedCodes 是除外故障代码集合；命中代码的请求一律拒绝。
18		ExcludedCodes map[string]struct{}
19	}
20	
21	// Part 是登记的备件及其库存。
22	type Part struct {
23		// ID 是唯一备件编号。
24		ID string
25		// Stock 是当前剩余实物库存，被成功使用的承诺分批扣减。
26		Stock int
27	}
28	
29	// Request 是提交的保修请求，指定产品和故障代码。
30	type Request struct {
31		// ID 是唯一请求编号。
32		ID string
33		// ProductID 是关联的产品编号。
34		ProductID string
35		// FaultCode 是故障代码，不能为空。
36		FaultCode string
37	}
38	
39	// CommitmentStatus 是承诺的当前状态。
40	type CommitmentStatus string
41	
42	const (
43		// CommitmentActive 表示承诺有效：未取消且未到期。
44		CommitmentActive CommitmentStatus = "active"
45		// CommitmentCanceled 表示承诺已被取消。
46		CommitmentCanceled CommitmentStatus = "canceled"
47		// CommitmentExpired 表示承诺已到期，余量自动释放。
48		CommitmentExpired CommitmentStatus = "expired"
49	)
50	
51	// Commitment 是一笔备件承诺。
52	type Commitment struct {
53		// ID 是全局唯一的提交编号。
54		ID string
55		// RequestID 是关联的请求编号。
56		RequestID string
57		// PartID 是预留的备件编号。
58		PartID string
59		// Quantity 是原定承诺数量（正整数）。
60		Quantity int
61		// Used 是已成功使用的累计数量。
62		Used int
63		// Expiry 是到期时刻；当前时刻等于或晚于它时承诺到期，余量释放。
64		Expiry time.Time
65		// Canceled 表示是否已被取消。
66		Canceled bool
67		// Expired 表示到期是否已被确认。到期确认是不可逆的结果：一经确认，
68		// 未用占用永久释放，之后即使传入更早的当前时刻也仍视为到期，不能重新
69		// 占用已释放给其他请求的数量。未确认前仅在当次时刻达到到期时刻时
70		// （库存查询、请求查询、新预留核算、新使用判断）就本次涉及的承诺确认。
71		// 幂等重试、参数非法或引用对象不存在而提前失败的调用不确认到期。
72		Expired bool
73	}
74	
75	// Unused 返回未用数量。
76	func (c *Commitment) Unused() int { return c.Quantity - c.Used }
77	
78	// confirmExpiryLocked 在已持锁的情况下按本次当前时刻确认单笔承诺到期。
79	// 仅确认本次操作涉及的承诺：未取消、尚未确认且当前时刻已达到到期时刻时
80	// 置位 Expired；该结果不可逆。已取消的承诺保持 canceled，不确认到期。
81	func (s *Store) confirmExpiryLocked(c *Commitment, now time.Time) {
82		if c.Canceled || c.Expired {
83			return
84		}
85		if !now.Before(c.Expiry) {
86			c.Expired = true
87		}
88	}
89	
90	// confirmExpiriesLocked 确认全部满足 match 的承诺中已到期但尚未确认的记录。
91	// 只确认本次操作涉及的承诺，不触碰其他对象的记录。
92	func (s *Store) confirmExpiriesLocked(match func(*Commitment) bool, now time.Time) {
93		for _, c := range s.commitments {
94			if match(c) {
95				s.confirmExpiryLocked(c, now)
96			}
97		}
98	}
99	
100	// confirmPartExpiriesLocked 确认指定备件下全部已到期但尚未确认的承诺。
101	func (s *Store) confirmPartExpiriesLocked(partID string, now time.Time) {
102		s.confirmExpiriesLocked(func(c *Commitment) bool { return c.PartID == partID }, now)
103	}
104	
105	// confirmRequestExpiriesLocked 确认指定请求下全部已到期但尚未确认的承诺。
106	func (s *Store) confirmRequestExpiriesLocked(requestID string, now time.Time) {
107		s.confirmExpiriesLocked(func(c *Commitment) bool { return c.RequestID == requestID }, now)
108	}
109	
110	// Status 返回承诺的当前状态。
111	// 已确认到期不可逆：即使传入更早的当前时刻也显示 expired；状态不要求
112	// 调用时刻递增。取消优先于到期，已取消的记录始终显示 canceled。
113	func (c *Commitment) Status(now time.Time) CommitmentStatus {
114		switch {
115		case c.Canceled:
116			return CommitmentCanceled
117		case c.Expired:
118			return CommitmentExpired
119		case !now.Before(c.Expiry):
120			return CommitmentExpired
121		default:
122			return CommitmentActive
123		}
124	}
125	
126	// Usage 是一次成功的承诺使用记录。
127	type Usage struct {
128		// ID 是全局唯一的使用编号。
129		ID string
130		// CommitmentID 是被扣减的承诺编号。
131		CommitmentID string
132		// Quantity 是本次使用的正整数数量。
133		Quantity int
134	}
135	
136	// Store 保存全部登记信息与承诺。所有方法均为并发安全。
137	type Store struct {
138		mu          sync.Mutex
139		products    map[string]*Product
140		parts       map[string]*Part
141		requests    map[string]*Request
142		commitments map[string]*Commitment
143		usages      map[string]*Usage
144		// firstResults 保存每个承诺编号首次预留成功时返回的承诺快照（已用数量为零、
145		// 未取消）。原样重试取回它，不随分批使用、取消或到期改变。
146		firstResults map[string]Commitment
147		// history 保存按请求分组的预留处理历史，仅存在于当前仓库实例中。
148		history map[string][]HistoryRecord
149	}
150	
151	// NewStore 创建一个空的保修备件仓库。
152	func NewStore() *Store {
153		return &Store{
154			products:     make(map[string]*Product),
155			parts:        make(map[string]*Part),
156			requests:     make(map[string]*Request),
157			commitments:  make(map[string]*Commitment),
158			usages:       make(map[string]*Usage),
159			firstResults: make(map[string]Commitment),
160			history:      make(map[string][]HistoryRecord),
161		}
162	}
163	
164	// RegisterProduct 登记产品：购买时刻、保修天数和除外故障代码。
165	// 编号重复时返回 ErrDuplicateID 且保留原记录；已存在的非空编号优先于其他
166	// 参数校验，即使新提交的保修天数、截止时刻或除外清单不合法也报编号重复，
167	// 原记录不被覆盖、清空或部分替换。保修天数必须为正整数，且自购买时刻起完整
168	// 天数（每天二十四小时）的截止时刻必须落在时间类型的可表示范围内，否则返回
169	// ErrInvalidParam，不保存产品记录。
170	func (s *Store) RegisterProduct(id string, purchaseTime time.Time, warrantyDays int, excludedCodes []string) error {
171		if id == "" {
172			return fmt.Errorf("%w: product id must not be empty", ErrInvalidParam)
173		}
174		s.mu.Lock()
175		defer s.mu.Unlock()
176		// 编号已存在时一律报重复并保留原记录，不再校验新提交的条款。
177		if _, ok := s.products[id]; ok {
178			return fmt.Errorf("%w: product %q", ErrDuplicateID, id)
179		}
180		if warrantyDays <= 0 {
181			return fmt.Errorf("%w: warranty days must be a positive integer", ErrInvalidParam)
182		}
183		// 截止时刻超出时间类型可表示范围的期限无法登记，不保存产品记录；
184		// 之后以同一编号提交可表示的条款仍可正常登记。
185		if _, ok := warrantyExpiry(purchaseTime, warrantyDays); !ok {
186			return fmt.Errorf("%w: warranty expiry for %d days is not representable", ErrInvalidParam, warrantyDays)
187		}
188		codes := make(map[string]struct{}, len(excludedCodes))
189		for _, c := range excludedCodes {
190			if c == "" {
191				return fmt.Errorf("%w: excluded fault code must not be empty", ErrInvalidParam)
192			}
193			codes[c] = struct{}{}
194		}
195		s.products[id] = &Product{
196			ID:            id,
197			PurchaseTime:  purchaseTime,
198			WarrantyDays:  warrantyDays,
199			ExcludedCodes: codes,
200		}
201		return nil
202	}
203	
204	// RegisterPart 登记备件及其非负整数初始库存。
205	// 编号重复时返回 ErrDuplicateID 且保留原记录：已存在的非空编号优先于本次
206	// 库存校验，即使再次提交的初始库存为负数或零，也一律报编号重复，重复登记
207	// 既不是补货也不会重置剩余库存，原备件的实物库存与承诺占用均保持不变。
208	// 未登记过的非空编号首次提交时，初始库存必须是非负整数，否则返回
209	// ErrInvalidParam，不保存备件记录、不占用编号；零库存也是有效登记。
210	func (s *Store) RegisterPart(id string, initialStock int) error {
211		if id == "" {
212			return fmt.Errorf("%w: part id must not be empty", ErrInvalidParam)
213		}
214		s.mu.Lock()
215		defer s.mu.Unlock()
216		// 编号已存在时一律报重复并保留原记录，不再校验本次提交的初始库存。
217		if _, ok := s.parts[id]; ok {
218			return fmt.Errorf("%w: part %q", ErrDuplicateID, id)
219		}
220		if initialStock < 0 {
221			return fmt.Errorf("%w: initial stock must be a non-negative integer", ErrInvalidParam)
222		}
223		s.parts[id] = &Part{ID: id, Stock: initialStock}
224		return nil
225	}
226	
227	// SubmitRequest 提交保修请求，指定产品和故障代码。
228	// 编号重复时返回 ErrDuplicateID 且保留原记录：已存在的非空编号优先于本次
229	// 参数校验，即使再次提交换了产品编号，或把故障代码改成空串等不合法内容，
230	// 也一律报编号重复，原请求的产品编号与故障代码不被覆盖、清空或部分替换，
231	// 资格依据、关联承诺与预留历史都继续按第一次成功提交的资料执行。
232	// 空请求编号或空故障代码的首次提交返回 ErrInvalidParam，不保存请求记录；
233	// 提交时不校验产品是否已登记，产品缺失留待资格查询与预留时报告。
234	func (s *Store) SubmitRequest(id, productID, faultCode string) error {
235		if id == "" {
236			return fmt.Errorf("%w: request id must not be empty", ErrInvalidParam)
237		}
238		s.mu.Lock()
239		defer s.mu.Unlock()
240		// 编号已存在时一律报重复并保留原记录，不再校验新提交的产品与故障代码。
241		if _, ok := s.requests[id]; ok {
242			return fmt.Errorf("%w: request %q", ErrDuplicateID, id)
243		}
244		if faultCode == "" {
245			return fmt.Errorf("%w: fault code must not be empty", ErrInvalidParam)
246		}
247		s.requests[id] = &Request{ID: id, ProductID: productID, FaultCode: faultCode}
248		return nil
249	}
250	
251	// Product 返回指定编号的产品副本，不存在时返回 ErrNotFound。
252	func (s *Store) Product(id string) (Product, error) {
253		s.mu.Lock()
254		defer s.mu.Unlock()
255		p, ok := s.products[id]
256		if !ok {
257			return Product{}, fmt.Errorf("%w: product %q", ErrNotFound, id)
258		}
259		cp := *p
260		cp.ExcludedCodes = make(map[string]struct{}, len(p.ExcludedCodes))
261		for k := range p.ExcludedCodes {
262			cp.ExcludedCodes[k] = struct{}{}
263		}
264		return cp, nil
265	}
266	
267	// Part 返回指定编号的备件副本，不存在时返回 ErrNotFound。
268	func (s *Store) Part(id string) (Part, error) {
269		s.mu.Lock()
270		defer s.mu.Unlock()
271		p, ok := s.parts[id]
272		if !ok {
273			return Part{}, fmt.Errorf("%w: part %q", ErrNotFound, id)
274		}
275		return *p, nil
276	}
277	
278	// Request 返回指定编号的请求副本，不存在时返回 ErrNotFound。
279	func (s *Store) Request(id string) (Request, error) {
280		s.mu.Lock()
281		defer s.mu.Unlock()
282		r, ok := s.requests[id]
283		if !ok {
284			return Request{}, fmt.Errorf("%w: request %q", ErrNotFound, id)
285		}
286		return *r, nil
287	}
288	
289	// Commitment 返回指定编号的承诺副本，不存在时返回 ErrNotFound。
290	func (s *Store) Commitment(id string) (Commitment, error) {
291		s.mu.Lock()
292		defer s.mu.Unlock()
293		c, ok := s.commitments[id]
294		if !ok {
295			return Commitment{}, fmt.Errorf("%w: commitment %q", ErrNotFound, id)
296		}
297		return *c, nil
298	}
299

