1	package warranty
2	
3	import (
4		"errors"
5		"testing"
6		"time"
7	)
8	
9	// 本文件回归保障“保修请求与产品资料已就绪、备件资料后登记”：产品与请求
10	// 都已保存且资格合格，但申请的备件编号尚未登记时，首次预留返回
11	// ErrNotFound——不自动创建备件或承诺，失败也不占用承诺编号；原请求仍可
12	// 查询、资格仍然合格、关联承诺列表为空。该次失败在原请求下留下一条
13	// part_not_found 历史，保存提交的承诺编号、备件编号、数量、到期时刻与
14	// 当次当前时刻，且资格依据与库存依据均为空：即使产品资料完整，这条提前
15	// 失败的记录也不能填成合格资格，尚未登记的备件不能解释成零库存。随后
16	// 补登备件库存（登记本身不替之前的申请预留数量），无需重新提交请求，
17	// 沿用原承诺编号、原备件、原数量与原到期时刻即可成功预留；历史依次保留
18	// 旧失败与本次成功，旧记录内容与空依据保持原样，不被成功覆盖或补写。
19	// 另覆盖补登库存不足的边界：备件缺失期间的失败保留后，只登记不足数量
20	// 的库存再沿用原提交内容预留，返回 ErrInsufficientStock，不创建承诺也
21	// 不做部分占用，历史追加 insufficient_stock 并保存当次真实依据。测试只
22	// 沿用既有公开入口与现有错误类别，不改变任何规则。
23	
24	// 本文件专用编号，避免与其他测试文件混用。
25	const (
26		pltProductID = "p-latepart"
27		pltPartID    = "part-latepart"
28		pltReqID     = "r-latepart"
29		pltCommitID  = "c-latepart"
30		pltFaultCode = "NOISE"
31	)
32	
33	// pltClock 汇集主例的全部时刻。
34	type pltClock struct {
35		purchase time.Time // 产品的购买时刻
36		deadline time.Time // 保修截止时刻：购买时刻起第三十天
37		firstAt  time.Time // 备件缺失期间首次预留的当次当前时刻
38		secondAt time.Time // 补登库存后重试预留的当次当前时刻
39		expiry   time.Time // 两次预留共用的到期时刻，晚于两次当前时刻
40	}
41	
42	// pltBaseScenario 构造主例：产品 p-latepart 已登记（购买时刻已到、保修
43	// 三十天、除外清单不含 NOISE），请求 r-latepart 已保存且故障代码非空；
44	// 备件 part-latepart 此刻尚未登记。
45	func pltBaseScenario(t *testing.T) (*Store, pltClock) {
46		t.Helper()
47		clk := pltClock{
48			purchase: t0,
49			deadline: t0.Add(30 * day),
50			firstAt:  t0.Add(10 * day),
51			secondAt: t0.Add(11 * day),
52			expiry:   t0.Add(45 * day),
53		}
54	
55		s := NewStore()
56		if err := s.RegisterProduct(pltProductID, clk.purchase, 30, []string{"BROKEN_SEAL"}); err != nil {
57			t.Fatalf("register product: %v", err)
58		}
59		if err := s.SubmitRequest(pltReqID, pltProductID, pltFaultCode); err != nil {
60			t.Fatalf("submit request: %v", err)
61		}
62		// 备件故意不登记，由各个用例在需要的时刻补登。
63		return s, clk
64	}
65	
66	// assertStock 断言备件账目为给定的实物剩余、有效占用与可承诺数量。
67	func pltAssertStock(t *testing.T, s *Store, now time.Time, phys, occupied, committable int) {
68		t.Helper()
69		st, err := s.PartStatus(pltPartID, now)
70		if err != nil {
71			t.Fatalf("part status: %v", err)
72		}
73		if st.PhysicalRemaining != phys || st.ActiveOccupied != occupied || st.Committable != committable {
74			t.Fatalf("stock = phys %d / occupied %d / committable %d, want %d/%d/%d",
75				st.PhysicalRemaining, st.ActiveOccupied, st.Committable, phys, occupied, committable)
76		}
77	}
78	
79	// assertEligible 断言原请求在当次时刻资格合格：购买时刻已到、保修未结束、
80	// 故障未命中除外，且没有拒绝原因。
81	func assertEligible(t *testing.T, e *Eligibility, clk pltClock) {
82		t.Helper()
83		if e == nil {
84			t.Fatal("eligibility basis missing")
85		}
86		if !e.Eligible || e.Excluded || len(e.Reasons) != 0 {
87			t.Fatalf("expected eligible without reasons, got %+v", e)
88		}
89		if e.RequestID != pltReqID || e.ProductID != pltProductID || e.FaultCode != pltFaultCode {
90			t.Fatalf("eligibility identity = %q/%q/%q, want %q/%q/%q",
91				e.RequestID, e.ProductID, e.FaultCode, pltReqID, pltProductID, pltFaultCode)
92		}
93		if !e.PurchaseTime.Equal(clk.purchase) || e.WarrantyDays != 30 || !e.WarrantyExpiry.Equal(clk.deadline) {
94			t.Fatalf("eligibility basis = (%v, %d, %v), want registered terms (%v, 30, %v)",
95				e.PurchaseTime, e.WarrantyDays, e.WarrantyExpiry, clk.purchase, clk.deadline)
96		}
97	}
98	
99	// assertMissingPartFailureRecord 断言备件缺失失败记录的完整内容：保存提交
100	// 的承诺编号、备件、数量、到期时刻与当次当前时刻；即使产品资料完整、资格
101	// 本来合格，这条提前失败的记录的资格依据与库存依据也都为空——尚未登记的
102	// 备件不能解释成零库存，也不能回填成合格资格。
103	func assertMissingPartFailureRecord(t *testing.T, rec HistoryRecord, seq int, clk pltClock) {
104		t.Helper()
105		if rec.Seq != seq {
106			t.Fatalf("seq = %d, want %d", rec.Seq, seq)
107		}
108		if rec.Success {
109			t.Fatalf("missing-part record marked success: %+v", rec)
110		}
111		if rec.Error != HistoryErrorPartNotFound {
112			t.Fatalf("error category = %q, want %q", rec.Error, HistoryErrorPartNotFound)
113		}
114		if rec.CommitID != pltCommitID || rec.PartID != pltPartID || rec.Quantity != 3 {
115			t.Fatalf("submission content = %q/%q/%d, want %q/%q/3",
116				rec.CommitID, rec.PartID, rec.Quantity, pltCommitID, pltPartID)
117		}
118		if !rec.Expiry.Equal(clk.expiry) || !rec.Now.Equal(clk.firstAt) {
119			t.Fatalf("times = expiry %v now %v, want %v / %v",
120				rec.Expiry, rec.Now, clk.expiry, clk.firstAt)
121		}
122		// 产品资料完整、资格本来合格，也不能把这条提前失败的记录填成合格资格。
123		if rec.Eligibility != nil {
124			t.Fatalf("missing-part record must have nil eligibility, got %+v", rec.Eligibility)
125		}
126		// 尚未登记的备件不能解释成零库存。
127		if rec.StockBasis != nil {
128			t.Fatalf("missing-part record must have nil stock basis, got %+v", rec.StockBasis)
129		}
130	}
131	
132	// TestReserveBeforePart_MissingPeriod 备件缺失期间：原请求仍可查询，资格
133	// 仍然合格，关联承诺列表为空；首次预留三件返回 ErrNotFound，不自动创建
134	// 备件或承诺，失败不占用承诺编号；历史留下一条 part_not_found 记录，保存
135	// 提交内容与当次时刻，资格依据与库存依据均为空。
136	func TestReserveBeforePart_MissingPeriod(t *testing.T) {
137		s, clk := pltBaseScenario(t)
138	
139		// 请求已保存：取回原产品编号与故障代码。
140		req, err := s.Request(pltReqID)
141		if err != nil {
142			t.Fatalf("request lookup: %v", err)
143		}
144		if req.ProductID != pltProductID || req.FaultCode != pltFaultCode {
145			t.Fatalf("saved request = %+v, want product %q fault %q", req, pltProductID, pltFaultCode)
146		}
147		// 备件确实尚未登记。
148		if _, err := s.Part(pltPartID); !errors.Is(err, ErrNotFound) {
149			t.Fatalf("part should be missing: got %v", err)
150		}
151	
152		// 资格仍然合格：购买时刻已到、保修期未结束、故障未被除外。
153		e, err := s.Evaluate(pltReqID, clk.firstAt)
154		if err != nil {
155			t.Fatalf("evaluate while part missing: %v", err)
156		}
157		assertEligible(t, e, clk)
158		// 按请求查看同样合格，且关联承诺列表为空。
159		view, err := s.RequestView(pltReqID, clk.firstAt)
160		if err != nil {
161			t.Fatalf("request view while part missing: %v", err)
162		}
163		assertEligible(t, view.Eligibility, clk)
164		if len(view.Commitments) != 0 {
165			t.Fatalf("no commitments expected before any success, got %+v", view.Commitments)
166		}
167	
168		// 首次预留三件（数量为正、到期时刻晚于当次时刻，失败原因确实只是备件
169		// 未登记）：返回 ErrNotFound，不能自动创建备件或承诺。
170		if _, err := s.Reserve(pltCommitID, pltReqID, pltPartID, 3, clk.expiry, clk.firstAt); !errors.Is(err, ErrNotFound) {
171			t.Fatalf("reserve while part missing: got %v, want ErrNotFound", err)
172		}
173		if _, err := s.Part(pltPartID); !errors.Is(err, ErrNotFound) {
174			t.Fatalf("failed reserve must not auto-register the part: got %v", err)
175		}
176		// 失败不占用承诺编号。
177		if _, err := s.Commitment(pltCommitID); !errors.Is(err, ErrNotFound) {
178			t.Fatalf("failed reserve created a commitment: got %v", err)
179		}
180		// 失败后原请求仍合格，关联承诺列表仍为空。
181		view, err = s.RequestView(pltReqID, clk.firstAt)
182		if err != nil {
183			t.Fatalf("request view after failed reserve: %v", err)
184		}
185		assertEligible(t, view.Eligibility, clk)
186		if len(view.Commitments) != 0 {
187			t.Fatalf("failed reserve gained commitments: %+v", view.Commitments)
188		}
189	
190		// 历史留下一条 part_not_found 失败记录，依据均为空。
191		h, err := s.RequestHistory(pltReqID)
192		if err != nil {
193			t.Fatalf("history: %v", err)
194		}
195		if len(h) != 1 {
196			t.Fatalf("history len = %d, want 1", len(h))
197		}
198		assertMissingPartFailureRecord(t, h[0], 1, clk)
199	}
200	
201	// TestReserveBeforePart_RegisterStockThenRetrySucceeds 随后为原备件编号登记
202	// 五件库存：登记本身不替之前的申请预留数量，此时实物五件、有效占用零件、
203	// 可承诺五件。原请求无需重新提交，再以原承诺编号、原备件、三件数量和原
204	// 到期时刻预留应成功；承诺归属原请求，账目变为 5/3/2。历史依次保留旧
205	// 失败与本次成功：成功记录的库存依据是新增占用前的 5/0/5，旧失败记录的
206	// 内容与空依据保持原样，不被成功覆盖或补写；请求的承诺列表只出现这笔
207	// 成功承诺。
208	func TestReserveBeforePart_RegisterStockThenRetrySucceeds(t *testing.T) {
209		s, clk := pltBaseScenario(t)
210	
211		// 备件缺失期间先失败一次，留下 seq=1 的 part_not_found 记录。
212		if _, err := s.Reserve(pltCommitID, pltReqID, pltPartID, 3, clk.expiry, clk.firstAt); !errors.Is(err, ErrNotFound) {
213			t.Fatalf("reserve while part missing: got %v, want ErrNotFound", err)
214		}
215	
216		// 补登五件库存：登记本身不替之前的申请预留数量。
217		if err := s.RegisterPart(pltPartID, 5); err != nil {
218			t.Fatalf("register part after failed reserve: %v", err)
219		}
220		pltAssertStock(t, s, clk.secondAt, 5, 0, 5)
221		// 原请求无需重新提交：资格仍合格，关联承诺列表仍为空。
222		view, err := s.RequestView(pltReqID, clk.secondAt)
223		if err != nil {
224			t.Fatalf("request view after part registration: %v", err)
225		}
226		assertEligible(t, view.Eligibility, clk)
227		if len(view.Commitments) != 0 {
228			t.Fatalf("part registration must not reserve for the earlier request, got %+v", view.Commitments)
229		}
230	
231		// 沿用原承诺编号、原备件、三件数量和原到期时刻再次预留：成功。
232		c, err := s.Reserve(pltCommitID, pltReqID, pltPartID, 3, clk.expiry, clk.secondAt)
233		if err != nil {
234			t.Fatalf("retry reserve after part registration: %v", err)
235		}
236		if c.ID != pltCommitID || c.RequestID != pltReqID || c.PartID != pltPartID ||
237			c.Quantity != 3 || c.Used != 0 || c.Canceled || c.Expired {
238			t.Fatalf("bad commitment: %+v", c)
239		}
240		if !c.Expiry.Equal(clk.expiry) {
241			t.Fatalf("commitment expiry = %v, want %v", c.Expiry, clk.expiry)
242		}
243	
244		// 账目变为：实物五件、有效占用三件、可承诺两件。
245		pltAssertStock(t, s, clk.secondAt, 5, 3, 2)
246	
247		// 请求的承诺列表只出现这笔成功承诺，不多出先前失败申请的记录。
248		view, err = s.RequestView(pltReqID, clk.secondAt)
249		if err != nil {
250			t.Fatalf("request view after success: %v", err)
251		}
252		if len(view.Commitments) != 1 {
253			t.Fatalf("commitments = %+v, want exactly the one successful commitment", view.Commitments)
254		}
255		d := view.Commitments[0]
256		if d.CommitmentID != pltCommitID || d.RequestID != pltReqID || d.PartID != pltPartID ||
257			d.OriginalQuantity != 3 || d.UsedQuantity != 0 || d.RemainingQuantity != 3 ||
258			d.Status != CommitmentActive || !d.Expiry.Equal(clk.expiry) {
259			t.Fatalf("commitment detail = %+v, want the successful 3-piece active commitment", d)
260		}
261	
262		// 历史两条：旧失败记录在前且内容与空依据保持原样；成功记录在后，
263		// 不覆盖也不补写前一条。
264		h, err := s.RequestHistory(pltReqID)
265		if err != nil {
266			t.Fatalf("history: %v", err)
267		}
268		if len(h) != 2 {
269			t.Fatalf("history len = %d, want 2", len(h))
270		}
271		assertMissingPartFailureRecord(t, h[0], 1, clk)
272		ok := h[1]
273		if ok.Seq != 2 || !ok.Success || ok.Error != "" {
274			t.Fatalf("second record should be success with seq 2: %+v", ok)
275		}
276		if ok.CommitID != pltCommitID || ok.PartID != pltPartID || ok.Quantity != 3 ||
277			!ok.Expiry.Equal(clk.expiry) || !ok.Now.Equal(clk.secondAt) {
278			t.Fatalf("success submission content: %+v", ok)
279		}
280		// 成功记录保存当次合格的资格依据。
281		assertEligible(t, ok.Eligibility, clk)
282		// 库存依据是新增占用前的五件实物、零件占用、五件可承诺。
283		if ok.StockBasis == nil {
284			t.Fatal("success record missing stock basis")
285		}
286		if ok.StockBasis.PhysicalRemaining != 5 || ok.StockBasis.ActiveOccupied != 0 ||
287			ok.StockBasis.Committable != 5 {
288			t.Fatalf("success stock basis = %+v, want pre-addition 5/0/5", ok.StockBasis)
289		}
290	}
291	
292	// TestReserveBeforePart_LateStockInsufficient 补登库存不足的边界：备件缺失
293	// 期间同样先申请三件并被拒绝（留下 part_not_found 记录），随后只登记两件
294	// 库存，再沿用原提交内容预留，返回 ErrInsufficientStock——不能创建承诺，
295	// 也不能只占用两件作为部分成功。账目保持 2/0/2，历史追加 insufficient_stock
296	// 并保存合格资格与当次真实库存依据，之前的 part_not_found 记录原样保留。
297	func TestReserveBeforePart_LateStockInsufficient(t *testing.T) {
298		s, clk := pltBaseScenario(t)
299	
300		// 备件缺失期间先申请三件并被拒绝，留下 seq=1 的 part_not_found 记录。
301		if _, err := s.Reserve(pltCommitID, pltReqID, pltPartID, 3, clk.expiry, clk.firstAt); !errors.Is(err, ErrNotFound) {
302			t.Fatalf("reserve while part missing: got %v, want ErrNotFound", err)
303		}
304	
305		// 只登记两件库存，不足申请的三件。
306		if err := s.RegisterPart(pltPartID, 2); err != nil {
307			t.Fatalf("register part with insufficient stock: %v", err)
308		}
309		pltAssertStock(t, s, clk.secondAt, 2, 0, 2)
310	
311		// 沿用原承诺编号、原备件、三件数量和原到期时刻再次预留：库存不足。
312		if _, err := s.Reserve(pltCommitID, pltReqID, pltPartID, 3, clk.expiry, clk.secondAt); !errors.Is(err, ErrInsufficientStock) {
313			t.Fatalf("reserve with insufficient late-registered stock: got %v, want ErrInsufficientStock", err)
314		}
315	
316		// 不能创建承诺，失败仍不占用编号。
317		if _, err := s.Commitment(pltCommitID); !errors.Is(err, ErrNotFound) {
318			t.Fatalf("insufficient-stock reserve created a commitment: got %v", err)
319		}
320		// 也不能只占用两件作为部分成功：账目保持两件、零件、两件。
321		pltAssertStock(t, s, clk.secondAt, 2, 0, 2)
322		// 请求下仍无任何承诺。
323		view, err := s.RequestView(pltReqID, clk.secondAt)
324		if err != nil {
325			t.Fatalf("request view after insufficient-stock reserve: %v", err)
326		}
327		assertEligible(t, view.Eligibility, clk)
328		if len(view.Commitments) != 0 {
329			t.Fatalf("insufficient-stock reserve gained commitments: %+v", view.Commitments)
330		}
331	
332		// 历史两条：之前的 part_not_found 记录原样保留在前；本次追加
333		// insufficient_stock，保存合格资格与当次真实库存依据 2/0/2。
334		h, err := s.RequestHistory(pltReqID)
335		if err != nil {
336			t.Fatalf("history: %v", err)
337		}
338		if len(h) != 2 {
339			t.Fatalf("history len = %d, want 2", len(h))
340		}
341		assertMissingPartFailureRecord(t, h[0], 1, clk)
342		ins := h[1]
343		if ins.Seq != 2 || ins.Success || ins.Error != HistoryErrorInsufficientStock {
344			t.Fatalf("second record should be insufficient_stock failure with seq 2: %+v", ins)
345		}
346		if ins.CommitID != pltCommitID || ins.PartID != pltPartID || ins.Quantity != 3 ||
347			!ins.Expiry.Equal(clk.expiry) || !ins.Now.Equal(clk.secondAt) {
348			t.Fatalf("insufficient-stock submission content: %+v", ins)
349		}
350		// 资格依据为当次合格资格。
351		assertEligible(t, ins.Eligibility, clk)
352		// 库存依据为当次真实账目：两件实物、零件占用、两件可承诺。
353		if ins.StockBasis == nil {
354			t.Fatal("insufficient-stock record missing stock basis")
355		}
356		if ins.StockBasis.PhysicalRemaining != 2 || ins.StockBasis.ActiveOccupied != 0 ||
357			ins.StockBasis.Committable != 2 {
358			t.Fatalf("insufficient-stock basis = %+v, want 2/0/2", ins.StockBasis)
359		}
360	}
361

